1	'use strict';
2	
3	const express = require('express');
4	const router = express.Router();
5	const fs = require('fs');
6	const path = require('path');
7	const os = require('os');
8	
9	const REGISTRY_PATH = path.join(os.homedir(), '.claude', 'org', 'registry.json');
10	
11	// Read registry fresh every call. Avoids Node's require() cache (which can hold
12	// stale data) AND avoids mid-write JSON.parse failures by catching + falling back.
13	function loadRegistry() {
14	  try {
15	    const raw = fs.readFileSync(REGISTRY_PATH, 'utf-8');
16	    return JSON.parse(raw);
17	  } catch (err) {
18	    // File missing OR mid-write JSON.parse failure → safe fallback.
19	    return { agents: {} };
20	  }
21	}
22	
23	function tokenize(text) {
24	  return text
25	    .toLowerCase()
26	    .replace(/[^a-z0-9\s]/g, ' ')
27	    .split(/\s+/)
28	    .filter(t => t.length > 2);
29	}
30	
31	/**
32	 * GET /api/dispatch/recommend?q=<free text>
33	 * Returns top agents ranked by skill overlap with the query.
34	 */
35	router.get('/dispatch/recommend', (req, res) => {
36	  const q = (req.query.q || '').trim();
37	  if (!q) return res.status(400).json({ error: 'q is required' });
38	
39	  const tokens = tokenize(q);
40	  if (tokens.length === 0) return res.json({ results: [] });
41	
42	  const registry = loadRegistry();
43	  const agents = registry.agents || {};
44	
45	  const scored = [];
46	
47	  for (const [id, agent] of Object.entries(agents)) {
48	    if (agent.status === 'retired') continue;
49	
50	    const skills = agent.skills || {};
51	    let rawScore = 0;
52	    const matchedSkills = [];
53	
54	    for (const token of tokens) {
55	      for (const [skillKey, skillData] of Object.entries(skills)) {
56	        // exact or substring match against skill key
57	        if (skillKey === token || skillKey.includes(token) || token.includes(skillKey)) {
58	          const contribution = (skillData.score || 0) * Math.log1p(skillData.hits || 0);
59	          rawScore += contribution;
60	          if (!matchedSkills.includes(skillKey)) matchedSkills.push(skillKey);
61	        }
62	      }
63	    }
64	
65	    if (rawScore > 0) {
66	      scored.push({
67	        agentId: id,
68	        name: agent.title ? `${id} — ${agent.title}` : id,
69	        department: agent.department || null,
70	        level: agent.levelTitle || null,
71	        tier: agent.tier || null,
72	        status: agent.status || 'active',
73	        score: rawScore,
74	        matchedSkills,
75	      });
76	    }
77	  }
78	
79	  // Normalize scores to 0-1 range
80	  const maxScore = scored.reduce((m, s) => Math.max(m, s.score), 1);
81	  scored.forEach(s => { s.score = Math.round((s.score / maxScore) * 100) / 100; });
82	
83	  scored.sort((a, b) => b.score - a.score);
84	
85	  res.json({ query: q, tokens, results: scored.slice(0, 5) });
86	});
87	
88	module.exports = router;
89	

