1	'use strict';
2	
3	const fs = require('fs');
4	const path = require('path');
5	const matter = require('gray-matter');
6	const atomicIo = require('./atomicIo');
7	
8	// ── Agent cache ─────────────────────────────────────────────────────────────
9	// Disk reads are the largest per-request cost for agent endpoints. We keep two
10	// in-process maps keyed by absolute path, invalidated by mtime. The PUT handler
11	// clears the corresponding entry after an atomic write. This is a single-process
12	// cache — if the server goes multi-process in future, move to Redis or similar.
13	const _agentCacheFull = new Map();
14	const _agentCacheMeta = new Map();
15	
16	function _invalidateAgentCache(filePath) {
17	  _agentCacheFull.delete(filePath);
18	  _agentCacheMeta.delete(filePath);
19	}
20	
21	// Register with atomicIo so that atomicWriteText auto-invalidates on agent writes.
22	atomicIo.setCacheInvalidator(_invalidateAgentCache);
23	
24	function parseAgent(filePath) {
25	  try {
26	    const stats = fs.statSync(filePath);
27	    const hit = _agentCacheFull.get(filePath);
28	    if (hit && hit.mtimeMs === stats.mtimeMs) return hit.parsed;
29	
30	    const content = fs.readFileSync(filePath, 'utf-8');
31	    const { data, content: body } = matter(content);
32	    const parsed = {
33	      filename: path.basename(filePath, '.md'),
34	      path: filePath,
35	      frontmatter: data,
36	      name: data.name || path.basename(filePath, '.md'),
37	      description: data.description || '',
38	      model: data.model || '',
39	      tools: data.tools || '',
40	      body: body.trim(),
41	      raw: content,
42	      updatedAt: stats.mtime.toISOString(),
43	    };
44	    _agentCacheFull.set(filePath, { mtimeMs: stats.mtimeMs, parsed });
45	    return parsed;
46	  } catch (e) {
47	    return null;
48	  }
49	}
50	
51	// Meta-only parse: reads just enough to extract frontmatter + body line count.
52	// Used by list endpoints so we never ship full bodies for a 30-item list.
53	function parseAgentMeta(filePath) {
54	  try {
55	    const stats = fs.statSync(filePath);
56	    const hit = _agentCacheMeta.get(filePath);
57	    if (hit && hit.mtimeMs === stats.mtimeMs) return hit.meta;
58	
59	    // Read until we've consumed the second '---' line; cheaper than reading the
60	    // whole body only to throw it away. For files without frontmatter, fall
61	    // back to a full read via parseAgent (rare).
62	    const fd = fs.openSync(filePath, 'r');
63	    const buf = Buffer.alloc(64 * 1024);
64	    let collected = '';
65	    let bytesRead = 0;
66	    let pos = 0;
67	    let frontmatterEnd = -1;
68	    const FM_RE = /^---\r?\n([\s\S]*?)\r?\n---\r?\n/;
69	    try {
70	      while (frontmatterEnd < 0) {
71	        const n = fs.readSync(fd, buf, 0, buf.length, pos);
72	        if (n === 0) break;
73	        collected += buf.slice(0, n).toString('utf-8');
74	        bytesRead += n;
75	        pos += n;
76	        const m = collected.match(FM_RE);
77	        if (m) frontmatterEnd = m[0].length;
78	        if (bytesRead > 256 * 1024 && frontmatterEnd < 0) break; // safety cap
79	      }
80	    } finally {
81	      fs.closeSync(fd);
82	    }
83	
84	    let data = {};
85	    if (frontmatterEnd > 0) {
86	      const parsed = matter(collected.slice(0, frontmatterEnd + 1024)); // buffer margin
87	      data = parsed.data || {};
88	    } else {
89	      // Fallback: full parse, rare case
90	      const full = parseAgent(filePath);
91	      if (!full) return null;
92	      return {
93	        filename: full.filename,
94	        path: full.path,
95	        frontmatter: full.frontmatter,
96	        name: full.name,
97	        description: full.description,
98	        model: full.model,
99	        tools: full.tools,
100	        bodyLines: full.body.split('\n').length,
101	        bodyChars: full.body.length,
102	        updatedAt: full.updatedAt,
103	      };
104	    }
105	
106	    // Compute body size cheaply from disk via stat + frontmatter length
107	    const totalSize = stats.size;
108	    const bodyChars = Math.max(0, totalSize - frontmatterEnd);
109	
110	    const meta = {
111	      filename: path.basename(filePath, '.md'),
112	      path: filePath,
113	      frontmatter: data,
114	      name: data.name || path.basename(filePath, '.md'),
115	      description: data.description || '',
116	      model: data.model || '',
117	      tools: data.tools || '',
118	      bodyLines: null, // deferred — callers that need line count use parseAgent
119	      bodyChars,
120	      updatedAt: stats.mtime.toISOString(),
121	    };
122	    _agentCacheMeta.set(filePath, { mtimeMs: stats.mtimeMs, meta });
123	    return meta;
124	  } catch (e) {
125	    return null;
126	  }
127	}
128	
129	function listAgents(dir) {
130	  try {
131	    if (!fs.existsSync(dir)) return [];
132	    return fs.readdirSync(dir)
133	      .filter(f => f.endsWith('.md'))
134	      .map(f => parseAgent(path.join(dir, f)))
135	      .filter(Boolean);
136	  } catch {
137	    return [];
138	  }
139	}
140	
141	// Meta-only variant — same ordering, same filter, just no body.
142	function listAgentsMeta(dir) {
143	  try {
144	    if (!fs.existsSync(dir)) return [];
145	    return fs.readdirSync(dir)
146	      .filter(f => f.endsWith('.md'))
147	      .map(f => parseAgentMeta(path.join(dir, f)))
148	      .filter(Boolean);
149	  } catch {
150	    return [];
151	  }
152	}
153	
154	module.exports = {
155	  _agentCacheFull,
156	  _agentCacheMeta,
157	  _invalidateAgentCache,
158	  parseAgent,
159	  parseAgentMeta,
160	  listAgents,
161	  listAgentsMeta,
162	};
163	

