1	/**
2	 * Experience Module — computes per-agent experience level, years of
3	 * experience, and skill vectors from multiple signals:
4	 *
5	 *   1. Training depth   → word count of the agent's .md file
6	 *   2. Tenure           → days since hiredAt
7	 *   3. Runs             → count from agent-runs.json
8	 *   4. Successes        → success_rate * run count
9	 *   5. Patterns         → patterns/good/*.md files where this agent is cited
10	 *   6. Antipatterns     → lessons/bugs.jsonl entries where agent_that_shipped matches
11	 *
12	 * The formula is deterministic, transparent, and tunable via
13	 * ~/.claude/org/experience-weights.json (optional override).
14	 *
15	 * YoE (years of experience) is scaled to feel human:
16	 *   ~10 KB of training content = 1 year
17	 *   ~20 runs = 1 year
18	 *   ~90 days of tenure = 1 year
19	 *
20	 * Levels map to human career titles from Trainee (0) to Distinguished (8).
21	 */
22	
23	const fs = require('fs');
24	const path = require('path');
25	const os = require('os');
26	
27	const HOME = os.homedir();
28	const CLAUDE_DIR = path.join(HOME, '.claude');
29	const AGENTS_DIR = path.join(CLAUDE_DIR, 'agents');
30	const MEMORY_DIR = path.join(CLAUDE_DIR, 'memory');
31	const WEIGHTS_PATH = path.join(CLAUDE_DIR, 'org', 'experience-weights.json');
32	
33	// Path to Polyglot's run-tracking files (caller-controlled in tests)
34	const POLYGLOT_ROOT = path.resolve(__dirname, '..');
35	const AGENT_RUNS_PATH = path.join(POLYGLOT_ROOT, 'agent-runs.json');
36	
37	// ──────────────────────────────────────────────────────────────────────────
38	//  Weights — tunable via ~/.claude/org/experience-weights.json
39	// ──────────────────────────────────────────────────────────────────────────
40	
41	const DEFAULT_WEIGHTS = {
42	  trainingKbPerYear: 10,   // 10 KB of .md content = 1 YoE
43	  runsPerYear: 20,         // 20 runs = 1 YoE
44	  daysPerYear: 90,         // 90 days tenure = 1 YoE
45	  patternWeight: 0.5,      // each pattern contributed = +0.5 YoE
46	  antipatternPenalty: 0.3, // each antipattern triggered = -0.3 YoE
47	  successBonus: 0.5,       // high success rate bonus (max +0.5 YoE)
48	};
49	
50	function loadWeights() {
51	  try {
52	    const dbModule = require('./db');
53	    const stored = dbModule.loadExperienceWeights();
54	    if (stored && Object.keys(stored).length > 0) return { ...DEFAULT_WEIGHTS, ...stored };
55	  } catch {}
56	  return { ...DEFAULT_WEIGHTS };
57	}
58	
59	// ──────────────────────────────────────────────────────────────────────────
60	//  Levels
61	// ──────────────────────────────────────────────────────────────────────────
62	
63	const LEVEL_THRESHOLDS = [
64	  { level: 0, title: 'Trainee',       minYoE: 0,    maxYoE: 1,  color: '#9ca3af', canMentor: false, canShipProd: false },
65	  { level: 1, title: 'Junior',        minYoE: 1,    maxYoE: 3,  color: '#6ee7b7', canMentor: false, canShipProd: false },
66	  { level: 2, title: 'Mid',           minYoE: 3,    maxYoE: 5,  color: '#34d399', canMentor: false, canShipProd: true },
67	  { level: 3, title: 'Senior',        minYoE: 5,    maxYoE: 8,  color: '#10b981', canMentor: true,  canShipProd: true },
68	  { level: 4, title: 'Lead',          minYoE: 8,    maxYoE: 12, color: '#3b82f6', canMentor: true,  canShipProd: true },
69	  { level: 5, title: 'Principal',     minYoE: 12,   maxYoE: 18, color: '#8b5cf6', canMentor: true,  canShipProd: true },
70	  { level: 6, title: 'Staff',         minYoE: 18,   maxYoE: 25, color: '#a855f7', canMentor: true,  canShipProd: true },
71	  { level: 7, title: 'Distinguished', minYoE: 25,   maxYoE: 40, color: '#f59e0b', canMentor: true,  canShipProd: true },
72	  { level: 8, title: 'Fellow',        minYoE: 40,   maxYoE: Infinity, color: '#eab308', canMentor: true, canShipProd: true },
73	];
74	
75	function levelForYoE(yoe) {
76	  for (let i = LEVEL_THRESHOLDS.length - 1; i >= 0; i--) {
77	    if (yoe >= LEVEL_THRESHOLDS[i].minYoE) return LEVEL_THRESHOLDS[i];
78	  }
79	  return LEVEL_THRESHOLDS[0];
80	}
81	
82	// ──────────────────────────────────────────────────────────────────────────
83	//  Signal collection
84	// ──────────────────────────────────────────────────────────────────────────
85	
86	function readAgentFileStats(agentId) {
87	  const mdPath = path.join(AGENTS_DIR, `${agentId}.md`);
88	  if (!fs.existsSync(mdPath)) {
89	    return { sizeBytes: 0, words: 0, lines: 0, exists: false };
90	  }
91	  try {
92	    const content = fs.readFileSync(mdPath, 'utf-8');
93	    const sizeBytes = Buffer.byteLength(content, 'utf-8');
94	    const words = content.split(/\s+/).filter(Boolean).length;
95	    const lines = content.split(/\n/).length;
96	    return { sizeBytes, words, lines, exists: true };
97	  } catch {
98	    return { sizeBytes: 0, words: 0, lines: 0, exists: false };
99	  }
100	}
101	
102	function loadAgentRuns() {
103	  try {
104	    const dbModule = require('./db');
105	    return dbModule.loadAgentRuns(10000);
106	  } catch {
107	    return [];
108	  }
109	}
110	
111	function computeRunStats(agentId, allRuns) {
112	  const runs = allRuns.filter((r) => r.agentName === agentId);
113	  const total = runs.length;
114	  const successes = runs.filter((r) => r.status === 'success').length;
115	  const failures = runs.filter((r) => r.status === 'failed' || r.status === 'error').length;
116	  const successRate = total > 0 ? successes / total : 0;
117	  const totalDuration = runs.reduce((s, r) => s + (r.duration || 0), 0);
118	  const avgDurationMs = total > 0 ? totalDuration / total : 0;
119	  const lastRunAt = runs.length > 0
120	    ? runs.map((r) => r.timestamp).sort().slice(-1)[0]
121	    : null;
122	  return { totalRuns: total, successRuns: successes, failedRuns: failures, successRate, avgDurationMs, lastRunAt };
123	}
124	
125	function countPatternsContributed(agentId) {
126	  const goodDir = path.join(MEMORY_DIR, 'patterns', 'good');
127	  if (!fs.existsSync(goodDir)) return 0;
128	  let count = 0;
129	  const files = fs.readdirSync(goodDir).filter((f) => f.endsWith('.md'));
130	  const needle = new RegExp(`\\b${agentId}\\b`, 'i');
131	  for (const f of files) {
132	    try {
133	      const content = fs.readFileSync(path.join(goodDir, f), 'utf-8');
134	      // Look in source/contributor blocks
135	      if (/source:|contributor:|author:/i.test(content) && needle.test(content)) {
136	        count++;
137	      }
138	    } catch {}
139	  }
140	  return count;
141	}
142	
143	function countAntipatternsTriggered(agentId) {
144	  const bugsPath = path.join(MEMORY_DIR, 'lessons', 'bugs.jsonl');
145	  if (!fs.existsSync(bugsPath)) return 0;
146	  try {
147	    const lines = fs.readFileSync(bugsPath, 'utf-8').split('\n').filter(Boolean);
148	    let count = 0;
149	    for (const line of lines) {
150	      try {
151	        const entry = JSON.parse(line);
152	        if (entry.agent_that_shipped === agentId || entry.agent === agentId) count++;
153	      } catch {}
154	    }
155	    return count;
156	  } catch {
157	    return 0;
158	  }
159	}
160	
161	// ──────────────────────────────────────────────────────────────────────────
162	//  Skill vector — keyword scan of agent .md body
163	// ──────────────────────────────────────────────────────────────────────────
164	
165	const SKILL_KEYWORDS = {
166	  react:        ['react', 'jsx', 'tsx', 'hooks', 'useeffect', 'usestate'],
167	  typescript:   ['typescript', 'tsc', 'strict mode', 'interface', 'generic'],
168	  nextjs:       ['next.js', 'nextjs', 'app router', 'server component', 'route handler'],
169	  supabase:     ['supabase', 'rls', 'row level security', 'postgres'],
170	  shopify:      ['shopify', 'polaris', 'admin api', 'storefront', 'embedded app'],
171	  billing:      ['stripe', 'dodo', 'billing', 'subscription', 'payment', 'checkout'],
172	  auth:         ['auth', 'oauth', 'session', 'jwt', 'magic link', 'otp'],
173	  testing:      ['test', 'vitest', 'jest', 'playwright', 'e2e', 'unit test'],
174	  design:       ['figma', 'design system', 'tailwind', 'shadcn', 'polaris'],
175	  seo:          ['seo', 'meta tags', 'sitemap', 'schema.org', 'core web vitals'],
176	  deployment:   ['deploy', 'railway', 'vercel', 'docker', 'ci/cd'],
177	  ai:           ['llm', 'prompt', 'streaming', 'tool use', 'anthropic', 'openai'],
178	  marketing:    ['landing page', 'copy', 'funnel', 'conversion', 'email campaign'],
179	  research:     ['validation', 'icp', 'persona', 'interview', 'market size'],
180	  debugging:    ['bug', 'stack trace', 'root cause', 'regression', 'incident'],
181	  architecture: ['architecture', 'data model', 'api design', 'scalab', 'system design'],
182	};
183	
184	function computeSkillVector(agentId) {
185	  const mdPath = path.join(AGENTS_DIR, `${agentId}.md`);
186	  if (!fs.existsSync(mdPath)) return {};
187	  try {
188	    const content = fs.readFileSync(mdPath, 'utf-8').toLowerCase();
189	    const skills = {};
190	    for (const [skill, keywords] of Object.entries(SKILL_KEYWORDS)) {
191	      let hits = 0;
192	      for (const kw of keywords) {
193	        const re = new RegExp(`\\b${kw.replace(/[.+*?^${}()|[\]\\]/g, '\\$&')}\\b`, 'g');
194	        const matches = content.match(re);
195	        if (matches) hits += matches.length;
196	      }
197	      if (hits > 0) {
198	        // Normalize: log-scale so a few hits ≈ 0.3, many hits ≈ 0.9
199	        const score = Math.min(1, Math.log10(hits + 1) / Math.log10(50));
200	        skills[skill] = { score: Math.round(score * 100) / 100, hits };
201	      }
202	    }
203	    return skills;
204	  } catch {
205	    return {};
206	  }
207	}
208	
209	function identifyWeaknesses(skills, threshold = 0.3) {
210	  return Object.entries(skills)
211	    .filter(([, data]) => data.score < threshold)
212	    .map(([skill]) => skill);
213	}
214	
215	// ──────────────────────────────────────────────────────────────────────────
216	//  Experience computation
217	// ──────────────────────────────────────────────────────────────────────────
218	
219	/**
220	 * Compute a full experience profile for one agent.
221	 *
222	 * @param {object} registryRecord — from ~/.claude/org/registry.json
223	 * @param {array}  allRuns        — from agent-runs.json (pass once for all agents)
224	 * @returns {object} Full experience profile to merge back into registry
225	 */
226	function computeExperience(registryRecord, allRuns) {
227	  const weights = loadWeights();
228	  const agentId = registryRecord.id;
229	  const hiredAt = registryRecord.hiredAt ? new Date(registryRecord.hiredAt) : new Date();
230	  const ageDays = Math.max(0, (Date.now() - hiredAt.getTime()) / (1000 * 60 * 60 * 24));
231	
232	  // 1. Training depth
233	  const fileStats = readAgentFileStats(agentId);
234	  const fileKb = fileStats.sizeBytes / 1024;
235	
236	  // 2. Run stats
237	  const runStats = computeRunStats(agentId, allRuns);
238	
239	  // 3. Pattern contributions
240	  const patternsContributed = countPatternsContributed(agentId);
241	
242	  // 4. Antipatterns triggered
243	  const antipatternsTriggered = countAntipatternsTriggered(agentId);
244	
245	  // 5. Compute YoE
246	  const yoeTraining = fileKb / weights.trainingKbPerYear;
247	  const yoeRuns = runStats.totalRuns / weights.runsPerYear;
248	  const yoeTenure = ageDays / weights.daysPerYear;
249	  const yoePatterns = patternsContributed * weights.patternWeight;
250	  const yoeSuccess = runStats.successRate * weights.successBonus;
251	  const yoeAntipatterns = -antipatternsTriggered * weights.antipatternPenalty;
252	
253	  const yearsOfExperience = Math.max(
254	    0,
255	    yoeTraining + yoeRuns + yoeTenure + yoePatterns + yoeSuccess + yoeAntipatterns
256	  );
257	
258	  // 6. Level from YoE
259	  const levelInfo = levelForYoE(yearsOfExperience);
260	
261	  // 7. Skills
262	  const skills = computeSkillVector(agentId);
263	  const weaknesses = identifyWeaknesses(skills);
264	
265	  // 8. Experience points (separate from YoE, used for UI progress bars)
266	  const experiencePoints = Math.round(yearsOfExperience * 100);
267	
268	  // 9. Next level threshold (for progress-to-next-level UI)
269	  const nextLevel = LEVEL_THRESHOLDS[levelInfo.level + 1] || null;
270	  const progressToNext = nextLevel
271	    ? Math.min(1, (yearsOfExperience - levelInfo.minYoE) / (nextLevel.minYoE - levelInfo.minYoE))
272	    : 1;
273	
274	  return {
275	    // Level
276	    level: levelInfo.level,
277	    levelTitle: levelInfo.title,
278	    levelColor: levelInfo.color,
279	    canMentor: levelInfo.canMentor,
280	    canShipProd: levelInfo.canShipProd,
281	    // Experience
282	    yearsOfExperience: Math.round(yearsOfExperience * 10) / 10,
283	    experiencePoints,
284	    progressToNext: Math.round(progressToNext * 100) / 100,
285	    nextLevelTitle: nextLevel?.title || null,
286	    // Breakdown (for HR UI transparency)
287	    breakdown: {
288	      training: Math.round(yoeTraining * 10) / 10,
289	      runs: Math.round(yoeRuns * 10) / 10,
290	      tenure: Math.round(yoeTenure * 10) / 10,
291	      patterns: Math.round(yoePatterns * 10) / 10,
