167	/**
168	 * Run the daily Witness sweep — classify recent runs, detect antipatterns,
169	 * compute daily scores, generate PIP/promotion recommendations.
170	 *
171	 * @param {object} orgModule    — src/org.js
172	 * @param {object} experienceModule — src/experience.js
173	 * @param {array}  agentRuns    — last 24h of agent-runs.json entries
174	 */
175	function runWitnessSweep(orgModule, experienceModule, agentRuns) {
176	  const startedAt = new Date().toISOString();
177	  const registry = orgModule.loadRegistry();
178	  const agents = registry.agents || {};
179	
180	  // 1. Classify each run in the window
181	  const cutoff = Date.now() - 24 * 60 * 60 * 1000;
182	  const recent = agentRuns.filter((r) => new Date(r.timestamp).getTime() >= cutoff);
183	  const classified = [];
184	
185	  for (const run of recent) {
186	    let classification = 'SUCCESS';
187	    if (run.status === 'failed' || run.status === 'error' || run.error) {
188	      classification = 'FAILURE';
189	    } else if (run.duration && run.duration > 600000) {
190	      classification = 'TIMEOUT';
191	    } else if (run.status === 'success') {
192	      classification = 'SUCCESS';
193	    } else {
194	      classification = 'UNCLASSIFIED';
195	    }
196	    const entry = logWitnessEvent({
197	      agent: run.agentName,
198	      runId: run.id,
199	      classification,
200	      meta: {
201	        durationMs: run.duration,
202	        taskType: run.taskType || 'general',
203	        project: run.metadata?.projectId || null,
204	      },
205	    });
206	    classified.push(entry);
207	  }
208	
209	  // 2. Compute daily scores
210	  const scoresByAgent = {};
211	  for (const entry of classified) {
212	    if (!scoresByAgent[entry.agent]) {
213	      scoresByAgent[entry.agent] = { agent: entry.agent, success: 0, failure: 0, antipattern: 0, regression: 0, score: 0 };
214	    }
215	    const s = scoresByAgent[entry.agent];
216	    if (entry.class === 'SUCCESS') s.success++;
217	    else if (entry.class === 'FAILURE' || entry.class === 'TIMEOUT') s.failure++;
218	    else if (entry.class === 'ANTIPATTERN') s.antipattern++;
219	    else if (entry.class === 'REGRESSION') s.regression++;
220	  }
221	  for (const s of Object.values(scoresByAgent)) {
222	    s.score = s.success * 1 - s.failure * 1 - s.antipattern * 2 - s.regression * 3;
223	    s.date = new Date().toISOString().slice(0, 10);
224	    dbModule.appendDailyScore(s);
225	  }
226	
227	  // 3. Generate PIP + promotion recommendations
228	  const pipCandidates = [];
229	  const promotionCandidates = [];
230	
231	  for (const id of Object.keys(agents)) {
232	    const a = agents[id];
233	    if (a.status === 'retired' || a.status === 'pip') continue;
234	
235	    const stats = a.stats || {};
236	    const successRate = stats.successRate ?? 1;
237	    const antipatterns = stats.antipatternsTriggered || 0;
238	
239	    // PIP triggers
240	    if (stats.totalRuns >= 20 && successRate < 0.7) {
241	      pipCandidates.push({
242	        agent: id,
243	        reasons: [`Success rate ${Math.round(successRate * 100)}%`],
244	        severity: successRate < 0.5 ? 'high' : 'medium',
245	      });
246	    } else if (antipatterns >= 3) {
247	      pipCandidates.push({
248	        agent: id,
249	        reasons: [`${antipatterns} antipatterns triggered`],
250	        severity: 'medium',
251	      });
252	    }
253	
254	    // Promotion eligibility — level crossed threshold, success rate high, 30+ days at level
255	    if (a.level != null && a.level < 8 && successRate >= 0.85 && antipatterns === 0) {
256	      const needsRuns = a.level >= 3 ? (stats.patternsContributed || 0) >= 1 : true;
257	      if (needsRuns) {
258	        promotionCandidates.push({
259	          agent: id,
260	          fromLevel: a.level,
261	          toLevel: a.level + 1,
262	          fromTitle: a.levelTitle,
263	          signals: [
264	            `${a.yearsOfExperience} YoE`,
265	            `${Math.round(successRate * 100)}% success`,
266	            `${stats.patternsContributed || 0} patterns`,
267	            `${antipatterns} antipatterns`,
268	          ],
269	        });
270	      }
271	    }
272	  }
273	
274	  const recommendations = {
275	    generatedAt: startedAt,
276	    completedAt: new Date().toISOString(),
277	    runsClassified: classified.length,
278	    pipCandidates,
279	    promotionCandidates,
280	  };
281	  dbModule.saveRecommendations(recommendations);
282	
283	  return recommendations;
284	}
