608	// GET /api/governance/cost — burn vs budget per tier + recent policy violations.
609	// Sprint 9 dashboard endpoint. Reads model_routing config + last-30d agent_runs
610	// to surface where Opus/Sonnet/Haiku spend is going and which agents are out
611	// of policy.
612	router.get('/governance/cost', rateLimit('read'), (_req, res) => {
613	  try {
614	    const policy = db.loadModelRouting() || {};
615	    const tiers = policy.tiers || {};
616	    const cutoff = new Date(Date.now() - 30 * 24 * 3600 * 1000).toISOString();
617	    const runs = db.getRecentAgentRuns(30 * 24);
618	
619	    // Build per-tier cost rollup
620	    const summary = {};
621	    const violations = [];
622	    for (const [tierKey, def] of Object.entries(tiers)) {
623	      summary[tierKey] = {
624	        model: def.shortName,
625	        agents: def.agents || [],
626	        runs: 0,
627	        estTokens: 0,
628	        estCostUsd: 0,
629	        budgetUsd: def.monthlyBudgetUsd || 0,
630	      };
631	    }
632	
633	    for (const r of runs) {
634	      const md = r.metadata || {};
635	      // Find which tier this agent belongs to
636	      const tierKey = Object.entries(tiers)
637	        .find(([, def]) => Array.isArray(def.agents) && def.agents.includes(r.agentName))?.[0];
638	      if (tierKey && summary[tierKey]) {
639	        summary[tierKey].runs += 1;
640	        summary[tierKey].estTokens += r.estimatedTokens || 0;
641	        summary[tierKey].estCostUsd += r.estimatedCost || 0;
642	      }
643	      if (md.policyViolation) {
644	        violations.push({
645	          runId: r.id,
646	          agentName: r.agentName,
647	          timestamp: r.timestamp,
648	          ...md.policyViolation,
649	        });
650	      }
651	    }
652	
653	    // Compute burn-pct per tier
654	    for (const t of Object.values(summary)) {
655	      t.estCostUsd = Math.round(t.estCostUsd * 100) / 100;
656	      t.burnPct = t.budgetUsd > 0 ? Math.round((t.estCostUsd / t.budgetUsd) * 100) : null;
657	    }
658	
659	    const totalEstCost = Object.values(summary).reduce((acc, t) => acc + t.estCostUsd, 0);
660	    const totalBudget = policy.totalMonthlyBudgetUsd || 0;
661	
662	    res.json({
663	      windowHours: 30 * 24,
664	      cutoff,
665	      enforcementMode: policy.enforcementMode || 'advisory',
666	      tiers: summary,
667	      total: {
668	        estCostUsd: Math.round(totalEstCost * 100) / 100,
669	        budgetUsd: totalBudget,
670	        burnPct: totalBudget > 0 ? Math.round((totalEstCost / totalBudget) * 100) : null,
671	      },
672	      violations: violations.slice(-50),
673	      violationCount: violations.length,
674	    });
675	  } catch (err) {
676	    res.status(500).json({ error: err.message });
677	  }
678	});
